"""Validate an operator-reviewed, source-hashed original C150911 site packet."""

import hashlib
import json
import math
from pathlib import Path

from crosswalk_delivery import validate_site


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def load_review(path, case_id):
    path = Path(path).resolve()
    document = json.loads(path.read_text())
    if document.get("case_id") != case_id or document.get("cell_id") != "C150911":
        raise ValueError("reviewed site case or cell identity differs")
    if document.get("review_status") != "original_native_reviewed":
        raise ValueError("original Native site review required")
    sources = document.get("sources")
    required = {"opendrive", "crosswalk", "pedestrian_access", "signal",
                "obstacles", "participants", "cameras"}
    if not isinstance(sources, dict) or not required <= sources.keys():
        raise ValueError("reviewed site source inventory incomplete")
    loaded = {}
    for name in sorted(required):
        ref = sources[name]
        if not isinstance(ref, dict) or not ref.get("path") or not ref.get("sha256"):
            raise ValueError("reviewed source binding missing: " + name)
        source = (path.parent / ref["path"]).resolve()
        if not source.is_relative_to(path.parent) or not source.is_file():
            raise ValueError("reviewed source path invalid: " + name)
        if _sha(source) != ref["sha256"]:
            raise ValueError("reviewed source changed: " + name)
        loaded[name] = source.read_text() if name == "opendrive" else json.loads(source.read_text())
    crosswalk = loaded["crosswalk"]
    for key in ("crosswalk_id", "one_way_road_id", "entry_center", "exit_center",
                "crosswalk_width_m", "crosswalk_vertices_xy_m"):
        if key not in crosswalk:
            raise ValueError("reviewed crosswalk geometry missing: " + key)
    vertices = crosswalk["crosswalk_vertices_xy_m"]
    if not isinstance(vertices, list) or len(vertices) < 4 or any(
            not isinstance(v, list) or len(v) != 2 or
            not all(type(x) in (int, float) and math.isfinite(x) for x in v)
            for v in vertices):
        raise ValueError("reviewed crosswalk polygon invalid")
    cameras = loaded["cameras"]
    if set(cameras) != {"overview", "approach", "reference_corner", "driver_reference"}:
        raise ValueError("four reviewed camera poses required")
    for name, row in cameras.items():
        for key in ("location_xyz_m", "pitch_yaw_roll_deg"):
            value = row.get(key)
            if not isinstance(value, list) or len(value) != 3 or not all(
                    type(x) in (int, float) and math.isfinite(x) for x in value):
                raise ValueError("reviewed camera pose invalid: " + name)
    access = loaded["pedestrian_access"]
    if access.get("pedestrian_access") is not True or not access.get("method"):
        raise ValueError("reviewed pedestrian access missing")
    signal = loaded["signal"]
    if signal.get("governing_signal") not in (
            "none_read_back", "pedestrian_walk", "pedestrian_dont_walk"):
        raise ValueError("reviewed pedestrian signal missing")
    site = {key: crosswalk[key] for key in ("crosswalk_id", "one_way_road_id",
            "entry_center", "exit_center", "crosswalk_width_m")}
    site["one_way_road_id"] = str(site["one_way_road_id"])
    site.update({"map_sha256": sources["opendrive"]["sha256"],
        "crosswalk_source_sha256": sources["crosswalk"]["sha256"],
        "access_source_sha256": sources["pedestrian_access"]["sha256"],
        "signal_source_sha256": sources["signal"]["sha256"],
        "obstacle_source_sha256": sources["obstacles"]["sha256"],
        "participant_source_sha256": sources["participants"]["sha256"],
        "pedestrian_source_sha256": document.get("pedestrian_source_sha256"),
        "crosswalk_qualification": "native_crosswalk_readback",
        "governing_signal": signal["governing_signal"],
        "pedestrian_access": True})
    validate_site(site)
    return {"review_sha256": _sha(path), "sources": sources,
            "source_data": loaded, "site": site}


def verify_native_map(world, reviewed):
    """Require exact original OpenDRIVE and mapped crosswalk points before spawning."""
    mapping = world.get_map()
    if hashlib.sha256(mapping.to_opendrive().encode()).hexdigest() != reviewed["site"]["map_sha256"]:
        raise ValueError("original Native OpenDRIVE readback differs")
    observed = [(float(p.x), float(p.y)) for p in mapping.get_crosswalks()]
    if not observed:
        raise ValueError("original Native crosswalk readback absent")
    for x, y in reviewed["source_data"]["crosswalk"]["crosswalk_vertices_xy_m"]:
        if not any(math.hypot(x - ox, y - oy) <= 0.25 for ox, oy in observed):
            raise ValueError("reviewed crosswalk vertex absent from Native readback")
    road_id = int(reviewed["site"]["one_way_road_id"])
    roads = [w for pair in mapping.get_topology() for w in pair if w.road_id == road_id]
    if not roads:
        raise ValueError("reviewed one-way road absent from Native topology")
    driving = [w for w in roads if str(getattr(w, "lane_type", "Driving")).endswith("Driving")]
    signs = {1 if w.lane_id > 0 else -1 for w in driving if w.lane_id != 0}
    if len(signs) != 1:
        raise ValueError("reviewed one-way road has opposing or absent Native driving lanes")
    return True

"""CPU construction and original-sample measurement for NRS 484B.293.

Right/left is defined relative to the pedestrian's direction of passage. The
returned geometry is an observation, never a legal practicability decision.
"""
from __future__ import annotations

import hashlib
import json
import math


def _point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("two-dimensional source point required")
    result = tuple(float(x) for x in value)
    if not all(math.isfinite(x) for x in result):
        raise ValueError("nonfinite source point")
    return result


def _vector(site):
    start, end = _point(site["entry_center"]), _point(site["exit_center"])
    dx, dy = end[0] - start[0], end[1] - start[1]
    length = math.hypot(dx, dy)
    if length < 2:
        raise ValueError("crosswalk passage too short")
    return start, length, (dx / length, dy / length), (dy / length, -dx / length)


def validate_site(site):
    """Reject ungrounded walkways and missing qualification/context sources."""
    for key in ("map_sha256", "crosswalk_source_sha256", "crosswalk_id",
                "one_way_road_id", "access_source_sha256", "signal_source_sha256",
                "obstacle_source_sha256", "participant_source_sha256",
                "pedestrian_source_sha256"):
        value = site.get(key)
        if not isinstance(value, str) or not value:
            raise ValueError("missing site source: " + key)
    if site.get("crosswalk_qualification") != "native_crosswalk_readback":
        raise ValueError("native crosswalk qualification readback required")
    width = float(site["crosswalk_width_m"])
    if not math.isfinite(width) or width <= 1:
        raise ValueError("invalid crosswalk width")
    _vector(site)
    if site.get("governing_signal") not in ("none_read_back", "pedestrian_walk",
                                             "pedestrian_dont_walk"):
        raise ValueError("governing pedestrian signal unknown")
    if site.get("pedestrian_access") is not True:
        raise ValueError("pedestrian access unverified")
    return True


def waypoints(site, side, stations=(0.0, 0.25, 0.5, 0.75, 1.0)):
    validate_site(site)
    if side not in ("right", "left"):
        raise ValueError("unknown half target")
    start, length, forward, right = _vector(site)
    offset = float(site["crosswalk_width_m"]) * (0.25 if side == "right" else -0.25)
    if any(not 0 <= float(s) <= 1 for s in stations):
        raise ValueError("station outside passage")
    return [(start[0] + forward[0] * length * s + right[0] * offset,
             start[1] + forward[1] * length * s + right[1] * offset)
            for s in stations]


def spawn_walk(site, side, adapter):
    """Lazy Native bridge; adapter owns blueprint, spawn and cleanup."""
    points = waypoints(site, side)
    walker = adapter.spawn_pedestrian(points[0], site["crosswalk_id"])
    if walker is None:
        raise ValueError("pedestrian spawn failed")
    try:
        adapter.set_pedestrian_route(walker, points)
    except Exception:
        adapter.destroy(walker)
        raise
    return walker, points


def measure(site, samples, obstacle_samples, participant_samples):
    """Measure full original 20 Hz passage and retain the raw stream."""
    validate_site(site)
    if not samples or not obstacle_samples or not participant_samples:
        raise ValueError("missing original participant/obstacle samples")
    start, length, forward, right = _vector(site)
    width = float(site["crosswalk_width_m"])
    if any(type(row.get("frame")) is not int for row in samples):
        raise ValueError("original frame identity invalid")
    frames = [row["frame"] for row in samples]
    if frames != list(range(frames[0], frames[0] + len(frames))):
        raise ValueError("nonconsecutive original frames")
    if any(type(row.get("elapsed_s")) not in (int, float) or
           not math.isfinite(row["elapsed_s"]) for row in samples):
        raise ValueError("original elapsed time invalid")
    times = [float(row["elapsed_s"]) for row in samples]
    if any(abs((times[i] - times[i - 1]) - 0.05) > 0.001 for i in range(1, len(times))):
        raise ValueError("original samples must be 20 Hz")
    for name, stream in (("obstacle", obstacle_samples), ("participant", participant_samples)):
        if [int(row["frame"]) for row in stream] != frames:
            raise ValueError(name + " frame join missing")
    trace = []
    pedestrian_id = samples[0].get("pedestrian_id")
    if not pedestrian_id:
        raise ValueError("original pedestrian identity missing")
    for row, obstacle, participant in zip(samples, obstacle_samples, participant_samples):
        if (row.get("pedestrian_id") != pedestrian_id or
            row.get("pedestrian_source_sha256") != site["pedestrian_source_sha256"]):
            raise ValueError("original pedestrian identity/source changed")
        if obstacle.get("source_sha256") != site["obstacle_source_sha256"]:
            raise ValueError("obstacle source binding differs")
        if participant.get("source_sha256") != site["participant_source_sha256"]:
            raise ValueError("participant source binding differs")
        x, y = _point(row["pedestrian_xy"])
        rel = (x - start[0], y - start[1])
        station = rel[0] * forward[0] + rel[1] * forward[1]
        lateral = rel[0] * right[0] + rel[1] * right[1]
        available = float(obstacle["available_right_width_m"])
        if not math.isfinite(available) or available < 0 or available > width / 2:
            raise ValueError("invalid available right width")
        if not isinstance(participant.get("participants"), list):
            raise ValueError("missing participant inventory")
        trace.append({"frame": row["frame"], "elapsed_s": float(row["elapsed_s"]),
                      "pedestrian_id": pedestrian_id,
                      "pedestrian_source": site["pedestrian_source_sha256"],
                      "station_m": station, "right_lateral_m": lateral,
                      "within_crosswalk": 0 <= station <= length and abs(lateral) <= width / 2,
                      "obstacle_source": obstacle["source_sha256"],
                      "participant_source": participant["source_sha256"],
                      "available_right_width_m": available,
                      "nearby_participants": participant["participants"]})
    return {"site_source_sha256": hashlib.sha256(json.dumps(site, sort_keys=True).encode()).hexdigest(),
            "fixed_sources": {key: site[key] for key in ("map_sha256", "crosswalk_source_sha256",
                              "crosswalk_id", "one_way_road_id", "access_source_sha256",
                              "signal_source_sha256", "obstacle_source_sha256",
                              "participant_source_sha256", "pedestrian_source_sha256")},
            "full_original_trace": trace, "right_half_sample_count": sum(r["right_lateral_m"] > 0 for r in trace),
            "crosswalk_sample_count": sum(r["within_crosswalk"] for r in trace),
            "legal_practicability": "unresolved"}


def audit_pair(left, right, deliberate_fields):
    """Independent exact-source comparison over saved measurement summaries."""
    required = {"site_source_sha256", "fixed_sources", "full_original_trace", "legal_practicability"}
    if not required <= set(left) or not required <= set(right):
        raise ValueError("missing saved measurement source")
    if left["legal_practicability"] != "unresolved" or right["legal_practicability"] != "unresolved":
        raise ValueError("unsupported practicability verdict")
    for key, value in left["fixed_sources"].items():
        if key not in deliberate_fields and value != right["fixed_sources"].get(key):
            raise ValueError("fixed site differs: " + key)
    for item in (left, right):
        if not item["full_original_trace"]:
            raise ValueError("missing original trace")
        frames = [r["frame"] for r in item["full_original_trace"]]
        if frames != list(range(frames[0], frames[0] + len(frames))):
            raise ValueError("gapped original trace")
    return {"passed": True, "fixed_sources_checked": sorted(set(left["fixed_sources"]) - set(deliberate_fields)),
            "compared_original_frames": [len(left["full_original_trace"]), len(right["full_original_trace"])]}

"""Independent saved-source checks for a later physical delivery attempt.

This checks packet completeness and source identity; it cannot establish that
the crosswalk was physically practicable or that pixels are readable.
"""
from __future__ import annotations

import hashlib
from pathlib import Path


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


def _file_hash(path):
    path = Path(path)
    if not path.is_file():
        raise ValueError("missing saved source: " + str(path))
    return hashlib.sha256(path.read_bytes()).hexdigest()


def audit_saved(packet, measurement, source_root):
    if packet.get("case_id") != measurement.get("case_id"):
        raise ValueError("case identity differs")
    if not packet.get("native_result_sha256") or not packet.get("frame_map_sha256"):
        raise ValueError("unsealed Native result or frame map")
    if packet.get("fps") != 20 or packet.get("frame_count", 0) < 2:
        raise ValueError("invalid original frame profile")
    if measurement.get("legal_practicability") != "unresolved":
        raise ValueError("unsupported practicability verdict")
    trace = measurement.get("full_original_trace")
    if not isinstance(trace, list) or len(trace) != packet["frame_count"]:
        raise ValueError("missing full original pedestrian trace")
    frames = [row.get("frame") for row in trace]
    if frames != list(range(frames[0], frames[0] + len(frames))):
        raise ValueError("gapped original frame map")
    if not any(row.get("within_crosswalk") for row in trace):
        raise ValueError("no observed crosswalk passage")
    pedestrian_id = trace[0].get("pedestrian_id")
    pedestrian_source = measurement["fixed_sources"].get("pedestrian_source_sha256")
    if not pedestrian_id or not pedestrian_source:
        raise ValueError("original pedestrian source missing")
    for row in trace:
        if (row.get("pedestrian_id") != pedestrian_id or
            row.get("pedestrian_source") != pedestrian_source):
            raise ValueError("original pedestrian identity/source join changed")
        if row.get("obstacle_source") != measurement["fixed_sources"].get("obstacle_source_sha256"):
            raise ValueError("missing original obstacle join")
        if row.get("participant_source") != measurement["fixed_sources"].get("participant_source_sha256"):
            raise ValueError("missing original participant join")
        if row.get("available_right_width_m") is None or row.get("nearby_participants") is None:
            raise ValueError("missing practicability context")
    sources = packet.get("sources")
    if not isinstance(sources, dict) or not sources:
        raise ValueError("missing sealed saved sources")
    actual = {}
    for key in ("native_result", "frame_map", *CAMERAS):
        item = sources.get(key)
        if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
            raise ValueError("missing saved source: " + key)
        path = (Path(source_root) / item["path"]).resolve()
        if not path.is_relative_to(Path(source_root).resolve()):
            raise ValueError("saved source escapes attempt")
        digest = _file_hash(path)
        if digest != item["sha256"]:
            raise ValueError("saved source hash differs: " + key)
        actual[key] = digest
    if actual["native_result"] != packet["native_result_sha256"]:
        raise ValueError("Native result binding differs")
    if actual["frame_map"] != packet["frame_map_sha256"]:
        raise ValueError("frame map binding differs")
    return {"passed": True, "case_id": packet["case_id"],
            "frame_count": packet["frame_count"], "source_sha256": actual,
            "physical_visibility": "unverified", "legal_practicability": "unresolved"}


def main():
    """Decode a sealed saved attempt independently; diagnostic runs stay labeled."""
    import argparse
    import json
    from independent_cpu_delivery import audit

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--case-id", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--diagnostic", action="store_true")
    args = parser.parse_args()
    result = audit(args.attempt, args.case_id, args.diagnostic)
    path = Path(args.output)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"case_id": args.case_id, "passed": True}))


if __name__ == "__main__":
    main()

